import discord4j.core.event.domain.interaction.InteractionCreateEvent;
import discord4j.core.object.command.ApplicationCommandInteractionOption;
import discord4j.rest.util.PermissionSet;
import reactor.core.publisher.Mono;

public class AddSlashCommand implements ISlashCommand {
	@Override
	public Mono<?> execute(final EEWBot bot, final InteractionCreateEvent event) throws Exception {
		if (!event.getInteraction().getGuildId().isPresent())
			return event.reply("DMチャンネルは利用できません (開発中)");

		final PermissionSet permission = event.getInteraction().getChannel()
			.flatMap(c -> c.getEffectivePermissions(bot.getClient().getSelfId()))
			.block();
		if (!permission.contains(discord4j.rest.util.Permission.VIEW_CHANNEL))
			return event.reply("Botはこのチャンネルを閲覧出来ません");
		if (!permission.contains(discord4j.rest.util.Permission.SEND_MESSAGES))
			return event.reply("Botはチャンネルにメッセージを投稿する権限がありません");

		final long channelID = event.getInteraction().getChannelId().asLong();
		Channel channel = bot.getChannels().get(channelID);
		if (channel==null) {
			channel = new Channel(false, false, true, false, false, SeismicIntensity.ONE);
			bot.getChannelsLock().writeLock().lock();
			bot.getChannels().put(channelID, channel);
			bot.getChannelsLock().writeLock().unlock();
		}

		final ApplicationCommandInteractionOption option = event.getInteraction().getCommandInteraction()
			.flatMap(cmd -> cmd.getOption(0))
			.orElseThrow();
		if (option.getValue().map(v -> v.asString()).orElse("").equals("all")) {
			channel.eewAlert = true;
			channel.eewPrediction = true;
			channel.quakeInfo = true;
			channel.monitor = true;

			bot.getChannelRegistry().save();
			return event.reply("全ての種類の情報をこのチャンネルに投稿します！");

