				return event.reply(this.choices.get(option.getValue().map(v -> v.asString()).orElse(""))+" は既に登録されています");

			channel.set(option.getValue().map(v -> v.asString()).orElse(""), true);

			bot.getChannelRegistry().save();
			return event.reply(this.choices.get(option.getValue().map(v -> v.asString()).orElse(""))+" をこのチャンネルに投稿します！");
