import com.helger.commons.collections.impl.CommonsArrayList;
import java.util.List;

public class SelectorAllSortedAll extends AbstractSelector
{
  @Nonnull
  public List <IChromosome> selectSurvivingChromosomes (@Nonnull final List <IChromosome> aChromosomes)
  {
    // Sort all chromosomes by descending fitness
    return new CommonsArrayList<>(ArrayHelper.getSortedInline (aChromosomes.toArray(new IChromosome[0]), new ComparatorChromosomeFitness (ESortOrder.DESCENDING)));
