import com.azure.messaging.eventhubs.EventHubClientBuilder;
import com.azure.messaging.eventhubs.EventHubConsumerAsyncClient;
import com.azure.messaging.eventhubs.EventPosition;
import com.azure.messaging.eventhubs.models.EventContext;
import com.azure.messaging.eventhubs.models.PartitionContext;
import java.time.Instant;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ReceiveByDateTime {
    public static void main(String[] args)
            throws ExecutionException, InterruptedException {

        final String connectionString = "Endpoint=sb://----ServiceBusNamespaceName-----.servicebus.windows.net/;SharedAccessKeyName=-----SharedAccessSignatureKeyName-----;SharedAccessKey=---SharedAccessSignatureKey----;EntityPath=----EventHubName-----";
        final ScheduledExecutorService executorService = Executors.newScheduledThreadPool(4);

        final EventHubConsumerAsyncClient consumer = new EventHubClientBuilder()
                .connectionString(connectionString)
                .consumerGroup(EventHubClientBuilder.DEFAULT_CONSUMER_GROUP_NAME)
                .buildAsyncConsumerClient();

        String partitionId = consumer.getPartitionIds().blockFirst();

        consumer.receiveFromPartition(partitionId, EventPosition.fromEnqueuedTime(Instant.EPOCH))
                .subscribe(eventContext -> {
                    EventData event = eventContext.getEventData();
                    System.out.print(String.format("Offset: %s, SeqNo: %s, EnqueueTime: %s",
                            event.getOffset(),
                            event.getSequenceNumber(),
                            event.getEnqueuedTime()));

                    if (event.getBody() != null) {
                        System.out.println(String.format("| Message Payload: %s", event.getBody().toString()));
                    }
                }, error -> {
                    System.err.println("Error occurred while receiving: " + error.toString());
                }, () -> {
                    System.out.println("Completed receiving events");
                });

        TimeUnit.SECONDS.sleep(30);

        consumer.close();
        executorService.shutdown();
    }
}
