    private void doSession(MqttChannel sessionChannel,
                           MqttChannel mqttChannel,
                           ChannelRegistry channelRegistry,
                           TopicRegistry topicRegistry,
                           MessageRegistry messageRegistry) {
        Set<String> topics = sessionChannel.getTopics();
        mqttChannel.setTopics(topics);
        topicRegistry.clearTopics(sessionChannel);
        topics.forEach(topic -> topicRegistry.register(topic, mqttChannel));
        channelRegistry.closeChannel(sessionChannel);
