import org.jline.reader.impl.completer.StringsCompleter;
import org.jline.terminal.Terminal;
import org.jline.terminal.TerminalBuilder;

public class JlineCliMain {
	public static void main(String[] args) throws IOException {
		Terminal terminal = TerminalBuilder.builder().build();
		LineReader reader = LineReaderBuilder.builder()
				.terminal(terminal)
				.completer(new Completer() {
					@Override
					public void complete(LineReader reader, ParsedLine line, List<Candidate> candidates) {
						String buffer = line.line().substring(0, line.cursor());
						for (String cmd : commandMap.keySet()) {
							if (cmd.startsWith(buffer)) {
								candidates.add(new Candidate(cmd));
							}
						}
					}
				})
				.build();
		String line;
		while ((line = reader.readLine("caixt>")) != null) {
			if(line.trim().equals("")){
				continue;
			}
			MyCommandOptions opts = new MyCommandOptions(line);
			if (opts.cmdArgs.size() < 1) {
				usage();
				continue;
			}
			if (!commandMap.containsKey(opts.command)) {
				usage();
				continue;
			}
			else if(line.startsWith("quit")){
				System.out.println("Quitting...");
				System.exit(0);
			}
			System.out.println(opts);
