        String libName = mwSALConfig.getLibName();
	LOG.info("Loading Middleware {}: Library={}", mwSALConfig.getMiddlewareName(), libName);

	String arch = System.getProperty("os.arch", "");

        for (String searchPath : mwSALConfig.getSearchPaths()) {
            NativeLibrary.addSearchPath(libName, searchPath);
        }

	// add arch specific paths
	if ("x86".equals(arch) || "i386".equals(arch)) {
	    for (String x32SearchPath : mwSALConfig.getX32SearchPaths()) {
		NativeLibrary.addSearchPath(libName, x32SearchPath);
	    }
	} else if ("amd64".equals(arch) || "ia64".equals(arch)) {
	    for (String x64SearchPath : mwSALConfig.getX64SearchPaths()) {
		NativeLibrary.addSearchPath(libName, x64SearchPath);
	    }
	}

	HashMap<String, Object> options = new HashMap<>();
	options.put("lib-index", libIdx++);
	if (SysUtils.isUnix()) {
	    // RTLD_LOCAL | RTLD_NOW
	    options.put(Library.OPTION_OPEN_FLAGS, 0x2);
	} else if (SysUtils.isMacOSX()) {
	    // RTLD_LOCAL | RTLD_NOW
	    options.put(Library.OPTION_OPEN_FLAGS, 0x6);
	}

	CryptokiLibrary tmpLib = (CryptokiLibrary) Native.loadLibrary(libName, CryptokiLibrary.class, options);
	nl = NativeLibrary.getInstance(libName, options);

	threadLock = new Semaphore(1, true);

	// determine whether we have to use the function pointers from C_GetFunctionList
	boolean hasInitialize = true;
	try {
	    nl.getFunction("C_Initialize");
	} catch (UnsatisfiedLinkError ex) {
	    hasInitialize = false;
	}

	if (! hasInitialize) {
	    LOG.info("Middleware module does not have a C_Initialize function. Falling back to C_GetFunctionList.");
	    tmpLib = new CryptokiLibraryWrapper(tmpLib);
	}
	lib = tmpLib;
    }
}

