public class StandardRequestFactory implements WebRequestFactory
{
    public WebRequest createRequest(String methodType, String url, Map<String, String> contents) throws Exception
    {
        WebRequest request = null;
        String body = null;
        if (contents != null && contents.get(BODY) != null)
        {
            body = contents.get(BODY);
        }

        HttpMethod method = HttpMethod.GET;
        if (methodType != null)
        {
            method = HttpMethod.valueOf(methodType.toUpperCase());
        }

        if (method != null)
        {
            URL theUrl = UrlUtils.toUrlUnsafe(url);
            request = new WebRequest(theUrl, method);
            if (body != null)
            {
                request.setRequestBody(body);
            }
            else
            {
                populateRequestParameters(contents, request);
            }
        }
        return request;
    }
}
