import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.NumericRangeQuery;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.search.TermQuery;
import org.apache.lucene.search.TopDocs;
import org.apache.lucene.store.Directory;
import org.apache.lucene.store.RAMDirectory;
import org.apache.lucene.util.Version;

public class PostcodeCheck {
  public Address getAddress(Address address, boolean debug) throws IOException {
    int limit = 20;
    Address result;

    try (IndexReader reader = DirectoryReader.open(index)) {
      BooleanQuery.Builder booleanQueryBuilder = new BooleanQuery.Builder();

      if (address.getPostcode() != null) {
        Query postcode = new TermQuery(new Term("postcode", address.getPostcode()));
        booleanQueryBuilder.add(postcode, BooleanClause.Occur.SHOULD);
      }
      if (address.getStreet() != null) {
        TermQuery streetTerm = new TermQuery(new Term("street", address.getStreet()));
        booleanQueryBuilder.add(streetTerm, BooleanClause.Occur.SHOULD);
        booleanQueryBuilder.add(new FuzzyQuery(new Term("street", address.getStreet())), BooleanClause.Occur.SHOULD);
      }
      if (address.getCity() != null) {
        booleanQueryBuilder.add(new FuzzyQuery(new Term("city", address.getCity())), BooleanClause.Occur.SHOULD);
        TermQuery cityTerm = new TermQuery(new Term("city", address.getCity()));
        booleanQueryBuilder.add(cityTerm, BooleanClause.Occur.SHOULD);
      }

      try {
        if (address.getHouseNumber() != null) {
          int houseNumber = Integer.parseInt(address.getHouseNumber());

          BooleanQuery.Builder oddEvenQueryBuilder = new BooleanQuery.Builder();
          oddEvenQueryBuilder.add(new TermQuery(new Term("numbertype", "mixed")), BooleanClause.Occur.SHOULD);
          if (houseNumber % 2 == 0) {
            oddEvenQueryBuilder.add(new TermQuery(new Term("numbertype", "even")), BooleanClause.Occur.SHOULD);
          } else {
            oddEvenQueryBuilder.add(new TermQuery(new Term("numbertype", "odd")), BooleanClause.Occur.SHOULD);
          }
          booleanQueryBuilder.add(oddEvenQueryBuilder.build(), BooleanClause.Occur.MUST);
          booleanQueryBuilder.add(NumericRangeQuery.newIntRange("minnumber", 0, houseNumber, houseNumber, true, true), BooleanClause.Occur.SHOULD);
          booleanQueryBuilder.add(NumericRangeQuery.newIntRange("maxnumber", houseNumber, 9999, 9999, true, true), BooleanClause.Occur.SHOULD);
        }
      } catch (NumberFormatException e) {
        // nothing to see, walk through...
      }

      result = searchAddress(limit, booleanQueryBuilder.build(), null, reader, debug, address);
    }
    if (result != null) {
      result.setHouseNumber(address.getHouseNumber());
      result.setHouseNumberAffix(address.getHouseNumberAffix());
    }
    return result;
  }
}
