            XSSFColor xssfColor = (XSSFColor) color;
            byte[] rgb = xssfColor.getRGB();
            if (rgb != null) {
                intRGB[0] = rgb[0] & 0xFF;
                intRGB[1] = rgb[1] & 0xFF;
                intRGB[2] = rgb[2] & 0xFF;
            }
        }
        return intRGB;
    }
}
