                    try {
                        fqp = QParser.getParser(fq, null, rb.req);
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                    try {
                        filters.add(fqp.getQuery());
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
            if (!filters.isEmpty()) {
                rb.setFilters(filters);
            }
        }

