import org.jeasy.batch.xml.XmlRecordMapper;
import org.jeasy.batch.xml.XmlRecordReader;
import org.jeasy.batch.core.record.Record;
import org.jeasy.batch.core.reader.RecordReader;
import org.jeasy.batch.core.reader.FileRecordReader;

public class ConfigReader {
    private void init() throws ConfigException {
        RecordReader<String> reader = new FileRecordReader(xmlFile);
        XmlRecordReader<String> xrr = new XmlRecordReader<>(reader, "CMD2RDF");
        try {
            xrr.open();
            Record<String> r = xrr.readRecord();
            if (r == null) {
                throw new ConfigException("The " + xmlFile.getAbsolutePath() + " isn't valid CMD2RDF config file.");
            }
            rawXmlContent = r.getPayload();
