                            final byte[] bytes = kryoSerializer.write(estimatedCall);
                            calls.add((EstimatedCall) kryoSerializer.read(bytes));

                            visitedCalls.add(estimatedCall);

                            matches.put(serviceJourneyId, calls);
                            break;
                        }
                    }
                }
            }
        }

        return matches;
    }
}

